// Generated by AI (UnitTest MCP)
//! Real PostgreSQL-gated coverage for Bridge's supervisor runtime inventory.

mod supervisor_api_support;

use std::time::SystemTime;

use ackplane_protocol::supervisor::{
    SupervisorLifecycleReason, SupervisorLifecycleReceipt, SupervisorRuntime, SupervisorSession,
    SupervisorWorkerState,
};
use ackplane_server::supervisor_store::{SupervisorLifecycleReceiptRequest, SupervisorStore};
use axum::{
    body::Body,
    http::{Method, Request, StatusCode},
};
use serde_json::json;
use supervisor_api_support::{
    application, body_json, enroll_repository, registration, unique_id, unix_seconds,
};
use tower::ServiceExt;

#[tokio::test]
async fn supervisor_inventory_is_tenant_scoped_ordered_and_redacted() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("supervisor-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    let node_id = enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let active_supervisor_id = format!("supervisor-active-{unique}");
    let never_supervisor_id = format!("supervisor-never-{unique}");
    let mut supervisors = SupervisorStore::connect(&database_url)
        .await
        .expect("connect Supervisor store for fixtures");
    let active_registration = supervisors
        .register(&registration(
            &tenant_id,
            &repository_id,
            &node_id,
            active_supervisor_id.clone(),
        ))
        .await
        .expect("register active supervisor");
    let never_registration = supervisors
        .register(&registration(
            &tenant_id,
            &repository_id,
            &node_id,
            never_supervisor_id.clone(),
        ))
        .await
        .expect("register never-heartbeated supervisor");
    let heartbeat = supervisors
        .record_heartbeat(&tenant_id, &repository_id, &active_supervisor_id)
        .await
        .expect("record active supervisor heartbeat");
    let started_at = i64::try_from(unix_seconds(SystemTime::now()))
        .expect("the current Unix second fits in i64")
        - 20;
    let session_id = format!("session-{unique}");
    let worker_id = format!("worker-{unique}");
    let session = SupervisorSession {
        session_id: session_id.clone(),
        supervisor_id: active_supervisor_id.clone(),
        worker_id: worker_id.clone(),
        runtime: SupervisorRuntime::Service,
        started_at,
        state: SupervisorWorkerState::Started,
    };
    let session_outcome = supervisors
        .record_session(&tenant_id, &repository_id, &session)
        .await
        .expect("record supervisor session");
    let first_receipt = supervisors
        .record_lifecycle(&SupervisorLifecycleReceiptRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            receipt: SupervisorLifecycleReceipt {
                supervisor_id: active_supervisor_id.clone(),
                session_id: session_id.clone(),
                worker_id: worker_id.clone(),
                occurred_at: started_at + 10,
                state: SupervisorWorkerState::Checkpointed,
                reason: None,
            },
            idempotency_key: format!("checkpoint-receipt-{unique}"),
        })
        .await
        .expect("record checkpoint receipt");
    let second_receipt = supervisors
        .record_lifecycle(&SupervisorLifecycleReceiptRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            receipt: SupervisorLifecycleReceipt {
                supervisor_id: active_supervisor_id.clone(),
                session_id: session_id.clone(),
                worker_id: worker_id.clone(),
                occurred_at: started_at + 20,
                state: SupervisorWorkerState::Paused,
                reason: Some(SupervisorLifecycleReason::DirectiveExpired),
            },
            idempotency_key: format!("pause-receipt-{unique}"),
        })
        .await
        .expect("record pause receipt");
    let app = application(&database_url, &tenant_id).await;

    let inventory = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/repositories/{repository_id}/supervisors"))
                .body(Body::empty())
                .expect("build supervisor inventory request"),
        )
        .await
        .expect("serve supervisor inventory route");
    assert_eq!(inventory.status(), StatusCode::OK);
    let inventory = body_json(inventory).await;
    assert_eq!(
        inventory,
        json!({
            "entries": [
                {
                    "supervisor_id": active_supervisor_id,
                    "node_id": node_id,
                    "supervisor_version": "1.0.0",
                    "protocol_version": "v1",
                    "supported_directives": ["notify", "terminate_force"],
                    "supports_checkpoint": true,
                    "supports_force_termination": true,
                    "outbox_durability": "persistent",
                    "recoverable_outbox": true,
                    "registered_at_seconds": unix_seconds(active_registration.status.registered_at),
                    "last_heartbeat_at_seconds": heartbeat.last_heartbeat_at,
                    "freshness": "current"
                },
                {
                    "supervisor_id": never_supervisor_id,
                    "node_id": node_id,
                    "supervisor_version": "1.0.0",
                    "protocol_version": "v1",
                    "supported_directives": ["notify", "terminate_force"],
                    "supports_checkpoint": true,
                    "supports_force_termination": true,
                    "outbox_durability": "persistent",
                    "recoverable_outbox": true,
                    "registered_at_seconds": unix_seconds(never_registration.status.registered_at),
                    "last_heartbeat_at_seconds": null,
                    "freshness": "never_reported"
                }
            ]
        })
    );

    let sessions = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/supervisors/{active_supervisor_id}/sessions"
                ))
                .body(Body::empty())
                .expect("build supervisor session request"),
        )
        .await
        .expect("serve supervisor session route");
    assert_eq!(sessions.status(), StatusCode::OK);
    assert_eq!(
        body_json(sessions).await,
        json!({
            "supervisor_id": active_supervisor_id,
            "entries": [{
                "session_id": session_id,
                "worker_id": worker_id,
                "runtime": "service",
                "state": "paused",
                "current_reason": "directive_expired",
                "started_at_seconds": started_at,
                "current_occurred_at_seconds": started_at + 20,
                "recorded_at_seconds": unix_seconds(session_outcome.projection.recorded_at)
            }]
        })
    );

    let lifecycle = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/supervisors/{active_supervisor_id}/sessions/{session_id}/lifecycle"
                ))
                .body(Body::empty())
                .expect("build supervisor lifecycle request"),
        )
        .await
        .expect("serve supervisor lifecycle route");
    assert_eq!(lifecycle.status(), StatusCode::OK);
    let lifecycle = body_json(lifecycle).await;
    assert_eq!(
        lifecycle,
        json!({
            "supervisor_id": active_supervisor_id,
            "session_id": session_id,
            "entries": [
                {
                    "receipt_position": first_receipt.receipt.receipt_position,
                    "worker_id": worker_id,
                    "occurred_at_seconds": started_at + 10,
                    "state": "checkpointed",
                    "reason": null,
                    "recorded_at_seconds": unix_seconds(first_receipt.receipt.recorded_at)
                },
                {
                    "receipt_position": second_receipt.receipt.receipt_position,
                    "worker_id": worker_id,
                    "occurred_at_seconds": started_at + 20,
                    "state": "paused",
                    "reason": "directive_expired",
                    "recorded_at_seconds": unix_seconds(second_receipt.receipt.recorded_at)
                }
            ]
        })
    );
    let lifecycle_text = lifecycle.to_string();
    for forbidden in [
        "idempotency_key",
        &format!("checkpoint-receipt-{unique}"),
        &format!("pause-receipt-{unique}"),
    ] {
        assert!(
            !lifecycle_text.contains(forbidden),
            "browser lifecycle data must not expose {forbidden}"
        );
    }

    for (method, route, expected_status) in [
        (
            Method::POST,
            format!("/api/v1/repositories/{repository_id}/supervisors"),
            StatusCode::METHOD_NOT_ALLOWED,
        ),
        (
            Method::GET,
            format!(
                "/api/v1/repositories/{repository_id}/supervisors/unknown-supervisor/sessions"
            ),
            StatusCode::NOT_FOUND,
        ),
        (
            Method::GET,
            format!(
                "/api/v1/repositories/{repository_id}/supervisors/{active_supervisor_id}/sessions/unknown-session/lifecycle"
            ),
            StatusCode::NOT_FOUND,
        ),
    ] {
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(route)
                    .body(Body::empty())
                    .expect("build refused supervisor request"),
            )
            .await
            .expect("serve refused supervisor request");
        assert_eq!(
            response.status(),
            expected_status,
            "read-only supervisor API must refuse unknown resources and mutations"
        );
    }

    let foreign_app = application(&database_url, &format!("foreign-{unique}")).await;
    let foreign_response = foreign_app
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/repositories/{repository_id}/supervisors"))
                .body(Body::empty())
                .expect("build foreign tenant request"),
        )
        .await
        .expect("serve foreign tenant request");
    assert_eq!(foreign_response.status(), StatusCode::NOT_FOUND);
}
